MATCH (equipment:Equipment)-[:measured_by]->(sensor:PlantItem), (sensor)-[:send_signal_to*0..]->(head:ProcessInstrumentationFunction {loop_tag: 'PAHH-53079'})
RETURN DISTINCT equipment.tag AS tag
ORDER BY tag;

MATCH (e:PlantItem {tag: 'E-5501'}), (t:PlantItem {tag: 'T-5501'}), (v:Valve)
WHERE EXISTS { (e)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(t) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag

MATCH (e:PlantItem {tag: 'D-5501'})-[:measured_by]->(i:PlantItem)
RETURN DISTINCT i.tag AS tag
ORDER BY tag;

MATCH (:PlantItem {tag: 'P-2903'})-[:is_drawn_on]->(s:Sheet)
RETURN DISTINCT s.sheet_id AS sheet_id
ORDER BY sheet_id;

MATCH (a:PlantItem {tag: 'EA-3101'}), (b:PlantItem {tag: 'P-3101'})
RETURN a.tag AS from_tag, b.tag AS to_tag,
       EXISTS {
         MATCH (a) ((:PlantItem)-[:line_to]->(n:PlantItem WHERE n.tag <> 'V-3101'))+ (b)
       } AS reachable_without_valve

MATCH (:PlantItem {tag: 'V-401'})-[:is_drawn_on]->(s:Sheet)
