MATCH (a:PlantItem {tag: 'E-5503'}), (b:PlantItem {tag: 'E-5501'})
RETURN a.tag AS source, b.tag AS destination,
       EXISTS {
         MATCH (a) ((x:PlantItem)-[:line_to]->(y:PlantItem)
           WHERE x.tag <> 'T-5501' AND y.tag <> 'T-5501')+ (b)
       } AS reachable

MATCH (f:PlantItem {tag: 'F-2501'}), (target:PlantItem {tag: 'V-2701'}), (v:Valve)
WHERE EXISTS { (f)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(target) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag

MATCH (a:PlantItem {tag: 'E-4802'}), (b:PlantItem {tag: 'P-4901'})
WHERE EXISTS {
  MATCH (a) ((x:PlantItem)-[:line_to]->(y:PlantItem) WHERE x.tag <> 'TV-49001' AND y.tag <> 'TV-49001')+ (b)
}
RETURN a.tag AS source_tag, b.tag AS destination_tag
ORDER BY source_tag, destination_tag

MATCH (a:PlantItem {tag: 'P-302'}), (b:PlantItem {tag: 'E-603'}), (v:Valve)
WHERE EXISTS { (a)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(b) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (a:PlantItem {tag: 'R-1101'}), (b:PlantItem {tag: 'P-1102'}), (e:PlantItem {tag: 'E-1101'})
RETURN EXISTS {
  MATCH (a) ((x)-[:line_to]->(y) WHERE x <> e AND y <> e)+ (b)
} AS reachable_without_E_1101

MATCH (a:PlantItem {tag: 'TK-4301'}), (b:PlantItem {tag: 'P-5002'})
RETURN a.tag AS from_tag, b.tag AS to_tag,
       EXISTS {
         MATCH (a) ((x:PlantItem)-[:line_to]->(y:PlantItem) WHERE y.tag <> 'P-4401')+ (b)
       } AS can_flow_without_P_4401

MATCH (a:PlantItem {tag: 'P-4201'}), (b:PlantItem {tag: 'EA-5301'}), (v:Valve)
WHERE EXISTS { (a)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(b) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (a:PlantItem {tag: 'V-801'}), (b:PlantItem {tag: 'V-1301'})
RETURN EXISTS {
  (a)-[:line_to*1..]->(b)
  WHERE NOT EXISTS {
    (a)-[:line_to*1..]->(e:PlantItem {tag: 'E-1301'})-[:line_to*1..]->(b)
  }
} AS reachable_without_E_1301

MATCH (start:PlantItem {tag: 'V-1701'}), (finish:PlantItem {tag: 'E-4901'}), (v:PlantItem:Valve)
WHERE EXISTS { (start)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(finish) }
RETURN count(DISTINCT v.tag) AS valve_count

MATCH (a:PlantItem {tag: 'P-3404'}), (b:PlantItem {tag: 'P-2702'})
MATCH p = shortestPath((a)-[:line_to*]->(b))
RETURN [n IN nodes(p) WHERE n.kind IN ['equipment', 'valve'] | n.tag] AS tags;

MATCH (:PlantItem {tag: 'FV-44002'})-[:line_to]->(item:PlantItem)
RETURN item.tag AS tag
ORDER BY tag;

