MATCH (loop:ProcessControlFunction {loop_tag: 'LIC-28003'})-[:send_signal_to*1..]->(actuator:PlantItem {kind: 'actuator'})-[:control]->(valve:Valve)
RETURN DISTINCT valve.tag AS tag
