MATCH (e:Equipment)-[:measured_by]->(s:PlantItem)-[:send_signal_to*0..]->(:ProcessInstrumentationFunction {loop_tag: 'TIAH-12006'})
RETURN DISTINCT e.tag AS tag
ORDER BY tag;

MATCH (a:PlantItem {unit_id: '9027'}), (b:PlantItem)
WHERE b.unit_id <> '9027'
  AND EXISTS { (a)-[:line_to*1..]->(b) }
RETURN DISTINCT b.unit_id AS unit_id, b.tag AS tag
ORDER BY unit_id, tag;

MATCH (f:PlantItem:FlameArrestor {unit_id: '1'})
RETURN f.tag AS tag
ORDER BY tag;

MATCH (p:PlantItem {tag: 'P-3601'}), (v:PlantItem:Valve), (e:PlantItem:Equipment)
WHERE EXISTS { (p)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(e) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (p:PlantItem {tag: 'P-4101'}), (v:PlantItem:Valve)
WHERE EXISTS { (p)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(:PlantItem:Equipment) }
  AND NOT EXISTS {
    MATCH (p)-[:line_to*1..]->(upstream:PlantItem:Valve)-[:line_to*1..]->(v)
  }
RETURN DISTINCT v.tag AS tag
ORDER BY tag

MATCH (source:PlantItem {tag: 'P-3401'})
MATCH (source)-[:line_to*1..]->(downstream:Equipment)
MATCH (v:Valve)
WHERE EXISTS { (source)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(downstream) }
  AND NOT EXISTS {
    MATCH (source)-[:line_to*1..]->(bypass:Valve)-[:line_to*1..]->(downstream)
    WHERE bypass <> v
  }
RETURN DISTINCT v.tag AS tag
ORDER BY tag

MATCH (p:PlantItem {tag: 'P-4101'}), (v:Valve)
WHERE EXISTS { (p)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(:Equipment) }
  AND NOT EXISTS {
    MATCH (p)-[:line_to*1..]->(u:Valve)
    WHERE u <> v AND EXISTS { (u)-[:line_to*1..]->(v) }
  }
RETURN DISTINCT v.tag AS tag
ORDER BY tag

MATCH (f:PlantItem {tag: 'F-2501'}), (v:Valve), (e:Equipment)
WHERE EXISTS { (f)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(e) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (p:PlantItem {tag: 'P-5502B'}), (v:Valve)
