ORDER BY tag;

MATCH (source:PlantItem {tag: 'P-4101'}), (v:Valve)
WHERE toLower(coalesce(v.category, '')) CONTAINS 'normally open'
  AND EXISTS { (source)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(:Equipment) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag

