MATCH (v:Valve)-[:line_to*1..]->(r:PlantItem {tag: 'R-1101'})
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (v:Valve)-[:line_to*1..]->(target:PlantItem {tag: 'V-1601'})
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (source:PlantItem {tag: 'F-2501'}), (valve:Valve)
WHERE EXISTS { (source)-[:line_to*1..]->(valve) }
  AND EXISTS { (valve)-[:line_to*1..]->(:Equipment) }
RETURN DISTINCT valve.tag AS tag
